function SectionLabel({ method, path }) {
  return (
    <div className="flex items-center gap-3 mb-3">
      <span className={`kr-badge ${method === "GET" ? "kr-badge-get" : "kr-badge-post"}`}>{method}</span>
      <span className="kr-mono kr-muted" style={{ fontSize: 12 }}>{path}</span>
    </div>
  );
}

function Reveal({ children, style }) {
  const ref = useRef(null);
  const [visible, setVisible] = useState(false);
  useEffect(() => {
    const el = ref.current;
    if (!el) return;
    const obs = new IntersectionObserver(
      ([entry]) => { if (entry.isIntersecting) { setVisible(true); obs.disconnect(); } },
      { threshold: 0.15 }
    );
    obs.observe(el);
    return () => obs.disconnect();
  }, []);
  return (
    <div ref={ref} className={`kr-reveal ${visible ? "in" : ""}`} style={style}>
      {children}
    </div>
  );
}

