function runCommand(raw) {
  const cmd = raw.trim().toLowerCase();
  switch (cmd) {
    case "": return [];
    case "help": return HELP_TEXT;
    case "whoami":
      return ["name:     Kashish Rastogi", "role:     Full-Stack Developer (Java / Spring Boot / React)",
        "location: Ghaziabad, India", "status:   200 OK — open to opportunities"];
    case "about":
      return ["B.Tech CS graduate (CGPA 8.19) who builds full-stack apps from the",
        "database up: REST APIs, JWT auth, and the React/Angular UIs on top",
        "of them. Recently exploring real-time systems with WebSockets."];
    case "experience":
      return ["SDE Intern @ NuZn Infotech — Jul 2025 to Sep 2025",
        "  Spring Boot + ReactJS + MySQL, JWT auth, WebSocket messaging,", "  RESTful APIs, JUnit + Postman testing."];
    case "projects":
      return PROJECTS.map((p, i) => `${i + 1}. ${p.name} · ${p.stack.join(", ")}`);
    case "skills":
      return TECH_CATEGORIES.map((cat) => `${cat.label.toLowerCase()}: ${cat.items.map((it) => it.label).join(", ")}`);
    case "education":
      return ["B.Tech CSE — IMS Engineering College, Ghaziabad (2022-2026), CGPA 8.19",
        "XII — Dayawati Modi Academy (2021-2022), 75%", "X   — Dayawati Modi Academy (2019-2020), 92.8%"];
    case "contact":
      return ["email: kashishrastogi13@gmail.com", "phone: +91 9917103529", "leetcode: leetcode.com/u/kashishrastogii"];
    case "sudo hire-me":
      return ["permission granted. let's talk — kashishrastogi13@gmail.com"];
    default:
      return [`bash: ${cmd}: command not found. type 'help' to see available commands.`];
  }
}
function Terminal() {
  const [history, setHistory] = useState([{ type: "sys", text: "kashish@dev:~$ type 'help' to get started" }]);
  const [input, setInput] = useState("");
  const bodyRef = useRef(null);
  useEffect(() => { if (bodyRef.current) bodyRef.current.scrollTop = bodyRef.current.scrollHeight; }, [history]);
  const submit = () => {
    const cmd = input;
    if (cmd.trim().toLowerCase() === "clear") { setHistory([]); setInput(""); return; }
    const output = runCommand(cmd);
    setHistory((h) => [...h, { type: "cmd", text: cmd }, ...output.map((t) => ({ type: "out", text: t }))]);
    setInput("");
  };
  return (
    <div className="kr-card" style={{ maxWidth: 620, margin: "0 auto", overflow: "hidden", textAlign: "left" }}>
      <div className="kr-mono" style={{ background: "#0F1115", padding: "10px 16px", display: "flex", alignItems: "center", gap: 8, borderBottom: "1px solid var(--line)" }}>
        <span style={{ width: 8, height: 8, borderRadius: "50%", background: "#FF5F57", display: "inline-block" }} />
        <span style={{ width: 8, height: 8, borderRadius: "50%", background: "#FEBC2E", display: "inline-block" }} />
        <span style={{ width: 8, height: 8, borderRadius: "50%", background: "#28C840", display: "inline-block" }} />
        <span style={{ color: "#8B8F98", fontSize: 12, marginLeft: 8 }}>bash — kashish@dev — try it</span>
      </div>
      <div ref={bodyRef} className="kr-mono" style={{ background: "#0F1115", color: "#D7DBE0", padding: "18px 20px", fontSize: 13, lineHeight: 1.85, minHeight: 150, maxHeight: 240, overflowY: "auto" }}>
        {history.map((line, i) => {
          if (line.type === "sys") return <div key={i} style={{ color: "#8A93A3" }}>{line.text}</div>;
          if (line.type === "cmd") return <div key={i}><span style={{ color: "#35D399" }}>$</span> {line.text}</div>;
          return <div key={i} style={{ color: "#B7BDC6", paddingLeft: 4 }}>{line.text}</div>;
        })}
        <div style={{ display: "flex", alignItems: "center", gap: 6, marginTop: 4 }}>
          <span style={{ color: "#35D399" }}>$</span>
          <input className="kr-terminal-input" value={input} onChange={(e) => setInput(e.target.value)}
            onKeyDown={(e) => { if (e.key === "Enter") submit(); }} autoComplete="off" spellCheck="false" placeholder="type a command..." />
        </div>
      </div>
    </div>
  );
}

