function polar(cx, cy, r, angleDeg) {
  const rad = (angleDeg * Math.PI) / 180;
  return { x: cx + r * Math.cos(rad), y: cy + r * Math.sin(rad) };
}

function TechGraph() {
  const [active, setActive] = useState(null); // { label, note, color }
  const CX = 325, CY = 325, LEAF_R = 195, COURSE_R = 140;
  const spreadFor = (n) => (n <= 1 ? 0 : Math.min(80, 19 * (n - 1)));
  const jitter = (i) => [-12, 0, 12][i % 3];

  return (
    <div className="flex" style={{ gap: 40, alignItems: "center", flexWrap: "wrap" }}>
      <svg width="100%" viewBox="0 0 650 650" style={{ flex: "1 1 560px", maxWidth: 680, display: "block", margin: "0 auto" }}>
        {/* KR -> category branches */}
        {TECH_CATEGORIES.map((cat) => {
          const catPos = polar(CX, CY, cat.catR, cat.angle);
          return <line key={cat.id} x1={CX} y1={CY} x2={catPos.x} y2={catPos.y} stroke="var(--line)" strokeWidth="1.5" />;
        })}

        {/* KR -> coursework branches (random, direct from center) */}
        {COURSE_ITEMS.map((item) => {
          const pos = polar(CX, CY, COURSE_R, item.angle);
          const isActive = active?.label === item.label;
          return (
            <line key={item.label} x1={CX} y1={CY} x2={pos.x} y2={pos.y}
              stroke={isActive ? "var(--muted)" : "var(--line-soft)"} strokeWidth={isActive ? 1.75 : 1.25}
              strokeDasharray="3 4" style={{ transition: "stroke .15s" }} />
          );
        })}

        {/* category -> leaf lines */}
        {TECH_CATEGORIES.map((cat) => {
          const catPos = polar(CX, CY, cat.catR, cat.angle);
          const n = cat.items.length;
          const spread = spreadFor(n);
          return cat.items.map((item, i) => {
            const itemAngle = cat.angle - spread / 2 + (spread / Math.max(1, n - 1)) * i;
            const leafPos = n === 1 ? polar(CX, CY, LEAF_R + jitter(i), cat.angle) : polar(CX, CY, LEAF_R + jitter(i), itemAngle);
            const isActive = active?.label === item.label;
            return (
              <line key={item.label} x1={catPos.x} y1={catPos.y} x2={leafPos.x} y2={leafPos.y}
                stroke={isActive ? cat.color : "var(--line)"} strokeWidth={isActive ? 2 : 1.5}
                style={{ transition: "stroke .15s" }} />
            );
          });
        })}

        {/* Category nodes */}
        {TECH_CATEGORIES.map((cat) => {
          const pos = polar(CX, CY, cat.catR, cat.angle);
          return (
            <g key={cat.id}>
              <circle cx={pos.x} cy={pos.y} r="6" fill={cat.color} />
              <text x={pos.x} y={pos.y - 14} textAnchor="middle" className="kr-mono" fontSize="12.5" fontWeight="700" fill="var(--muted)" style={{ textTransform: "uppercase", letterSpacing: "0.04em" }}>
                {cat.label}
              </text>
            </g>
          );
        })}

        {/* Skill leaf nodes */}
        {TECH_CATEGORIES.map((cat) =>
          cat.items.map((item, i) => {
            const n = cat.items.length;
            const spread = spreadFor(n);
            const itemAngle = cat.angle - spread / 2 + (spread / Math.max(1, n - 1)) * i;
            const r = LEAF_R + jitter(i);
            const pos = n === 1 ? polar(CX, CY, r, cat.angle) : polar(CX, CY, r, itemAngle);
            const isActive = active?.label === item.label;
            const labelDx = Math.cos((itemAngle * Math.PI) / 180) >= 0 ? 1 : -1;
            const setThis = () => setActive({ ...item, color: cat.color });
            return (
              <g key={item.label} style={{ cursor: "pointer" }}
                onMouseEnter={setThis}
                onMouseLeave={() => setActive((a) => (a?.label === item.label ? null : a))}
                onClick={() => setActive(isActive ? null : { ...item, color: cat.color })}>
                <circle cx={pos.x} cy={pos.y} r={isActive ? 10 : 8} fill={isActive ? cat.color : "var(--surface)"}
                  stroke={cat.color} strokeWidth="1.5" style={{ transition: "all .15s" }} />
                <text x={pos.x + labelDx * 15} y={pos.y + 4.5} textAnchor={labelDx > 0 ? "start" : "end"}
                  className="kr-mono" fontSize="12.5" fontWeight={isActive ? 700 : 500}
                  fill={isActive ? "var(--ink)" : "var(--muted)"} style={{ transition: "all .15s" }}>
                  {item.label}
                </text>
              </g>
            );
          })
        )}

        {/* Coursework nodes - dimmer, direct off center */}
        {COURSE_ITEMS.map((item) => {
          const pos = polar(CX, CY, COURSE_R, item.angle);
          const isActive = active?.label === item.label;
          const labelDx = Math.cos((item.angle * Math.PI) / 180) >= 0 ? 1 : -1;
          return (
            <g key={item.label} style={{ cursor: "pointer" }}
              onMouseEnter={() => setActive({ ...item, color: "var(--muted)" })}
              onMouseLeave={() => setActive((a) => (a?.label === item.label ? null : a))}
              onClick={() => setActive(isActive ? null : { ...item, color: "var(--muted)" })}>
              <circle cx={pos.x} cy={pos.y} r={isActive ? 8 : 6} fill={isActive ? "var(--muted)" : "var(--surface)"}
                stroke="var(--muted)" strokeWidth="1" opacity={isActive ? 1 : 0.7} style={{ transition: "all .15s" }} />
              <text x={pos.x + labelDx * 12} y={pos.y + 4.5} textAnchor={labelDx > 0 ? "start" : "end"}
                className="kr-mono" fontSize="11" fontWeight={isActive ? 700 : 500}
                fill={isActive ? "var(--ink)" : "var(--muted)"} opacity={isActive ? 1 : 0.75} style={{ transition: "all .15s" }}>
                {item.label}
              </text>
            </g>
          );
        })}

        {/* Center node */}
        <circle cx={CX} cy={CY} r="24" fill="var(--surface)" stroke="var(--green)" strokeWidth="2" />
        <text x={CX} y={CY + 4.5} textAnchor="middle" className="kr-mono" fontSize="12.5" fontWeight="700" fill="var(--ink)">KR</text>
      </svg>

      <div style={{ flex: "1 1 240px", maxWidth: 320 }}>
        <h4 className="kr-mono kr-muted" style={{ fontSize: 11, letterSpacing: "0.05em", marginBottom: 14, textTransform: "uppercase" }}>Selected skill</h4>
        {active ? (
          <div>
            <div className="kr-mono" style={{ fontWeight: 700, fontSize: 15, color: active.color, marginBottom: 8 }}>{active.label}</div>
            <p style={{ fontSize: 13.5, lineHeight: 1.65, color: "var(--ink)" }}>{active.note}</p>
          </div>
        ) : (
          <p className="kr-muted" style={{ fontSize: 13, lineHeight: 1.6 }}>Hover or tap any dot in the graph to see where it's actually been used.</p>
        )}
      </div>
    </div>
  );
}

