function MessageBox() {
  const [name, setName] = useState("");
  const [email, setEmail] = useState("");
  const [msg, setMsg] = useState("");
  const [error, setError] = useState(false);
  const [sending, setSending] = useState(false);
  const [sent, setSent] = useState(false);

  const send = () => {
    if (!name.trim() || !msg.trim()) {
      setError(true);
      setSent(false);
      return;
    }
    setError(false);
    setSending(true);

    emailjs.send(
      "service_61x2mch",
      "template_7vpzf0t",
      {
        name: name,
        email: email || "not provided",
        message: msg,
        time: new Date().toLocaleString(),
      },
      "RbkvqsXlPJ4P9SwHU"
    )
      .then(() => {
        setSent(true);
        setName("");
        setEmail("");
        setMsg("");
      })
      .catch((err) => {
        console.error(err);
        setError(true);
      })
      .finally(() => setSending(false));
  };

  const field = (label, placeholder, value, onChange, isTextarea) => (
    <div style={{ marginBottom: 18 }}>
      <label className="kr-muted" style={{ display: "block", fontSize: 13, marginBottom: 7 }}>{label}</label>
      {isTextarea ? (
        <textarea className="kr-input" placeholder={placeholder} rows={5} value={value} onChange={onChange} style={{ resize: "vertical", fontFamily: "inherit" }} />
      ) : (
        <input className="kr-input" placeholder={placeholder} value={value} onChange={onChange} />
      )}
    </div>
  );

  return (
    <div>
      <h3 className="kr-display" style={{ fontSize: 18, fontWeight: 700, marginBottom: 18 }}>Send me a message</h3>
      {field("Your name", "What's your name?", name, (e) => setName(e.target.value))}
      {field("Your email", "What's your email?", email, (e) => setEmail(e.target.value))}
      {field("Your message", "What would you like to say?", msg, (e) => setMsg(e.target.value), true)}
      <p className="kr-muted" style={{ fontSize: 11.5, marginBottom: 14 }}></p>
      <button onClick={send} className="kr-btn-primary kr-mono" style={{ width: "100%", padding: "13px 18px", borderRadius: 8, fontSize: 13, fontWeight: 700, letterSpacing: "0.04em", border: "none", cursor: "pointer", display: "flex", alignItems: "center", justifyContent: "center", gap: 8, textTransform: "uppercase" }}>
        Send message <Send size={13} />
      </button>
      {sent && <p className="kr-mono" style={{ fontSize: 12, color: "var(--green)", marginTop: 10 }}>Sending your message…</p>}
      {error && <p className="kr-mono" style={{ fontSize: 12, color: "var(--amber)", marginTop: 10 }}>Name and message are required.</p>}
    </div>
  );
}

